<script setup lang="ts">
import { ref, onMounted, computed } from 'vue'
import { useAuthStore } from '@/stores/auth'
import { usePlayerStore } from '@/stores/player'
import { Capacitor } from '@capacitor/core'
import { App } from '@capacitor/app'
import { Haptics, ImpactStyle } from '@capacitor/haptics'

const authStore = useAuthStore(); const playerStore = usePlayerStore()
const showAdSkip = ref(playerStore.adSkipEnabled); const showEqualizer = ref(false); const showDataSaver = ref(false); const cacheSize = ref('0 MB'); const appVersion = ref('2.0.0')
async function load() { showAdSkip.value = playerStore.adSkipEnabled; try { if (Capacitor.isNativePlatform()) { const i = await App.getInfo(); appVersion.value = `${i.version} (${i.build})` } } catch {} }
function fmtCache(b: number) { if (b < 1024) return `${b} B`; if (b < 1024*1024) return `${(b/1024).toFixed(1)} KB`; return `${(b/(1024*1024)).toFixed(1)} MB` }
async function clearCache() { Haptics.impact({ style: ImpactStyle.Medium }); try { if ('caches' in window) { const n = await caches.keys(); await Promise.all(n.map(x => caches.delete(x))) } cacheSize.value = '0 MB' } catch { console.error('Failed to clear cache') } }
async function logout() { Haptics.impact({ style: ImpactStyle.Heavy }); await authStore.logout() }
onMounted(() => { load(); if ('storage' in navigator && 'estimate' in navigator.storage) navigator.storage.estimate().then(e => { cacheSize.value = fmtCache(e.usage || 0) }) })
</script>

