      <div class="card"><h3 class="section-title px-4">Playback</h3><div class="space-y-4 px-4 py-4"><div class="flex items-center justify-between"><div><p class="font-medium">Ad Skip</p><p class="text-xs text-gray">Automatically skip ads when detected</p></div><button @click="showAdSkip=!showAdSkip; playerStore.setAdSkipEnabled(showAdSkip)" class="relative w-12 h-6 rounded-full transition-colors" :class="showAdSkip?'bg-green':'bg-gray'" aria-label="Ad Skip Toggle" role="switch" :aria-checked="showAdSkip"><span class="absolute top-0.5 left-0.5 w-5 h-5 rounded-full bg-white shadow transition-transform" :style="{ transform: showAdSkip ? 'translateX(100%)' : 'translateX(0)' }"></span></button></div><div class="flex items-center justify-between"><div><p class="font-medium">Equalizer</p><p class="text-xs text-gray">Adjust audio frequencies (coming soon)</p></div><button class="icon-btn p-2" :class="showEqualizer?'text-green':''" @click="showEqualizer=!showEqualizer"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 19h6v-6H4v6zm8-6h6v-6h-6v6zm8 12h6v-18h-6v18z"></path></svg></button></div><div class="flex items-center justify-between"><div><p class="font-medium">Data Saver</p><p class="text-xs text-gray">Reduce data usage (coming soon)</p></div><button @click="showDataSaver=!showDataSaver" class="relative w-12 h-6 rounded-full transition-colors" :class="showDataSaver?'bg-green':'bg-gray'" aria-label="Data Saver Toggle" role="switch" :aria-checked="showDataSaver"><span class="absolute top-0.5 left-0.5 w-5 h-5 rounded-full bg-white shadow transition-transform" :style="{ transform: showDataSaver ? 'translateX(100%)' : 'translateX(0)' }"></span></button></div></div></div>
      <div class="card"><h3 class="section-title px-4">Storage</h3><div class="space-y-4 px-4 py-4"><div class="flex items-center justify-between"><div><p class="font-medium">Cache Size</p><p class="text-xs text-gray">Temporary files for faster loading</p></div><span class="text-sm text-gray">{{ cacheSize }}</span></div><button @click="clearCache" class="w-full flex items-center justify-center gap-2 px-4 py-2 bg-gray rounded-lg text-sm font-medium hover:bg-gray/50 transition-colors"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path></svg><span>Clear Cache</span></button></div></div>
      <div class="card"><h3 class="section-title px-4">About</h3><div class="space-y-4 px-4 py-4"><div class="flex items-center justify-between"><div><p class="font-medium">Version</p><p class="text-xs text-gray">App version</p></div><span class="text-sm text-gray">{{ appVersion }}</span></div><div class="flex items-center justify-between"><div><p class="font-medium">Open Source Licenses</p><p class="text-xs text-gray">View third-party licenses</p></div><button class="icon-btn p-2 text-xs" aria-label="Licenses"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 18 15 12 9 6"></polyline></svg></button></div><div class="flex items-center justify-between"><div><p class="font-medium">Privacy Policy</p><p class="text-xs text-gray">Read our privacy policy</p></div><button class="icon-btn p-2 text-xs" aria-label="Privacy"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 18 15 12 9 6"></polyline></svg></button></div></div></div>
      <div class="card"><button @click="logout" class="w-full flex items-center justify-center gap-3 px-4 py-3 bg-error/20 rounded-lg text-error font-medium hover:bg-error/30 transition-colors"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"></path><polyline points="16 17 21 12 16 7"></polyline><line x1="21" y1="12" x2="9" y2="12"></line></svg><span>Log Out</span></button></div>
      <div class="text-center text-xs text-gray px-4"><p>Spotify Mobile v2.0.0</p><p>Built with Capacitor, Vue 3, and Spotify Web Playback SDK</p><p class="mt-2">Not affiliated with Spotify AB</p></div>
    </div>
  </div>
</template>